    ay = a[1] * y[1] + a[2] * y[2] + a[3] * y[3]
    aa = a[1]^2 + a[2]^2 + a[3]^2
    äy = ä[1] * y[1] + ä[2] * y[2] + ä[3] * y[3]
    return q, ay, aa, äy
end

